declare(strict_types=1);namespace Atlas\Platform\Workflows\Repositories;use Atlas\Platform\Workflows\Domain\Workflow;use Atlas\Platform\Workflows\Domain\WorkflowStep;final class WordPressWorkflowRepository implements WorkflowRepository{private string$w;private string$v;private string$s;public function __construct(private object$db){$this->w=$db->prefix.'atlas_workflows';$this->v=$db->prefix.'atlas_workflow_versions';$this->s=$db->prefix.'atlas_workflow_steps';}public function findPublishedForContext(string$id,?string$org):?Workflow{$row=$this->db->get_row($this->db->prepare("SELECT w.id,w.scope,w.organization_id,w.slug,v.id version_id,v.title,v.summary,v.version_number,v.source_resource_version_id FROM `{$this->w}` w INNER JOIN `{$this->v}` v ON v.id=w.current_version_id WHERE w.id=%s AND v.status='published' AND (w.scope IN ('platform','public') OR (w.scope='organization' AND w.organization_id=%s)) LIMIT 1",$id,$org??''),ARRAY_A);if(!is_array($row)){return null;}$rows=$this->db->get_results($this->db->prepare("SELECT id,step_position,title,instruction,requirement_text,warning_text,related_resource_id FROM `{$this->s}` WHERE workflow_version_id=%s ORDER BY step_position ASC,id ASC",(string)$row['version_id']),ARRAY_A);$steps=is_array($rows)?array_map(static fn(array$r):WorkflowStep=>new WorkflowStep((string)$r['id'],(int)$r['step_position'],(string)$r['title'],(string)$r['instruction'],(string)$r['requirement_text'],$r['warning_text']===null?null:(string)$r['warning_text'],$r['related_resource_id']===null?null:(string)$r['related_resource_id']),$rows):[];return new Workflow((string)$row['id'],(string)$row['scope'],$row['organization_id']===null?null:(string)$row['organization_id'],(string)$row['slug'],(string)$row['title'],(string)$row['summary'],(int)$row['version_number'],$row['source_resource_version_id']===null?null:(string)$row['source_resource_version_id'],$steps);}}
